package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_14_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Test case where both CharSequences are null
        assertTrue(StringUtils.equals(null, null));

        // Test case where one CharSequence is null
        assertFalse(StringUtils.equals(null, "abc"));
        assertFalse(StringUtils.equals("abc", null));

        // Test case where both CharSequences are empty
        assertTrue(StringUtils.equals("", ""));

        // Test case where CharSequences are equal
        assertTrue(StringUtils.equals("abc", "abc"));

        // Test case where CharSequences are not equal
        assertFalse(StringUtils.equals("abc", "ABC"));
        assertFalse(StringUtils.equals("abc", "abcd"));

        // Test case with different CharSequence implementations
        CharSequence cs1 = new StringBuilder("abc");
        CharSequence cs2 = new StringBuilder("abc");
        assertTrue(StringUtils.equals(cs1, cs2));
    }
}

